{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "The closest analogue, KNI-272, had an absolute oral bioavailability of 54.97 ± 19.78% in fasting patients at 10 mg/kg, well above the 20% threshold; other adult fasting doses gave 29.56–33.99%, all above threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Atazanavir, a high-transfer HIV protease inhibitor, has an absolute oral bioavailability of 68% (57–80%) in humans, supporting high F for this peptidomimetic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Darunavir, a hydroxyethylamine HIV protease inhibitor sharing the core pharmacophore, has an oral bioavailability of 37% when given alone, still above the 20% threshold despite P-gp/CYP3A4 liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In children, KNI-272 given with Ora-Plus had a mean absolute F of 12% (range 3.5–25%), below the threshold, indicating that pediatric formulation/population can reduce bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alvimopan, a structurally distant peptidomimetic opioid antagonist, has a human oral bioavailability of only 6%, but its low transfer and deliberate design for low systemic exposure limit relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a peptidomimetic HIV-protease-inhibitor-like molecule. The closest analogue KNI-272 shows adult absolute oral bioavailability values of ~30–55%, all above the 20% threshold. Other high-transfer HIV protease inhibitors (atazanavir, darunavir) also show F ≥37–90%. Low-F molecules such as alvimopan and ergotamine have much lower transfer and lack the relevant scaffold, so high bioavailability is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "The closest analogue KNI-272 shows lower F in children (12%) with a specific vehicle, so pediatric/formulation extrapolation is uncertain.",
    "Food effects and dose-dependent absorption for the query are not directly known."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

